const body = $input.first().json.body || $input.first().json;
const message = body.message || '';
const source = body.source || 'chat_widget';
const url = body.url || '';
const timestamp = body.timestamp || new Date().toISOString();

return [{
  json: {
    body: message.substring(0, 2000),
    subject: 'Chat widget message',
    sender: 'website_visitor',
    gmailId: null,
    threadId: null,
    source,
    url,
    timestamp
  }
}];

const response = $input.first().json;
let classification;
try {
  const text = response.text || response.output || JSON.stringify(response);
  const jsonMatch = text.match(/\{[\s\S]*\}/);
  classification = JSON.parse(jsonMatch ? jsonMatch[0] : text);
} catch(e) {
  classification = {
    category: 'FAQ',
    priority: 'P2',
    language: 'HR',
    summary: 'Could not parse classification',
    requires_human: true,
    suggested_action: 'Manual review needed',
    auto_reply: ''
  };
}

// Sanitize summary to prevent injection into Slack
if (classification.summary) {
  classification.summary = classification.summary.substring(0, 200).replace(/[<>]/g, '');
}

const chatData = $('Extract Chat Message').first().json;

return [{
  json: {
    ...chatData,
    ...classification
  }
}];

const data = $('Parse Classification').first().json;
const autoReply = data.auto_reply || '';

let fallbackReply;
if (!autoReply) {
  fallbackReply = data.language === 'HR'
    ? 'Hvala na vašoj poruci! Naš tim će vam odgovoriti uskoro. Za hitne upite: support@metabelly.com'
    : 'Thank you for your message! Our team will get back to you shortly. For urgent enquiries: support@metabelly.com';
}

return [{
  json: {
    auto_reply: autoReply || fallbackReply,
    category: data.category,
    priority: data.priority,
    requires_human: data.requires_human
  }
}];
